<?php

namespace MongoDB\BSON;

use stdClass;

/**
 * <div id="class.mongodb-bson-persistable" class="reference"> <h1 class="title">The MongoDB\BSON\Persistable interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-persistable.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Classes may implement this interface to take advantage of automatic ODM    (object document mapping) behavior in the extension. During serialization,    the extension will inject a <span class="property">__pclass</span> property    containing the PHP class name into the data returned by    <span class="function">{@link MongoDB\BSON\Serializable::bsonSerialize()}</span>. During    unserialization, the same <span class="property">__pclass</span> property will then    be used to infer the PHP class (independent of any    <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">type map</a> configuration)    to be constructed before    <span class="function">{@link MongoDB\BSON\Unserializable::bsonUnserialize()}</span> is    invoked. See <a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a> for additional    information.   </p>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     Even if <span class="function">{@link MongoDB\BSON\Serializable::bsonSerialize()}</span> would     return a sequential array, injection of the <span class="property">__pclass</span>     property will cause the object to be serialized as a BSON document.    </span>   </p></blockquote>  </div>  <div class="section" id="mongodb-bson-persistable.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Persistable</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-unserializable.php" class="interfacename">MongoDB\BSON\Unserializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-persistable.bsonserialize.php" class="methodname" style="color:#CC7832">bsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 继承的方法 </div>    <div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Serializable::bsonSerialize}</span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="type MongoDB\BSON\PackedArray" style="color:#EAB766">MongoDB\BSON\PackedArray</a></span></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Unserializable::bsonUnserialize}</span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Persistable::bsonSerialize} — Provides an array or document to serialize as BSON</li></ul></div>
 * 
 * Classes may implement this interface to take advantage of automatic ODM (object document mapping) behavior in the driver.
 * @link https://php.net/manual/zh/class.mongodb-bson-persistable.php
 */
interface Persistable extends Unserializable, Serializable
{
/**
 * <div id="mongodb-bson-persistable.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Persistable::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Persistable::bsonSerialize</span> — <span class="dc-title">Provides an array or document to serialize as BSON</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-persistable.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Persistable::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span></span></div>  <p class="simpara">   Called during serialization of the object to BSON. The method must return an   <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>, or   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>.  </p>  <p class="simpara">   The return value will always be serialized as a BSON document. The serialized   document will include a field containing the class name of the object. For   this reason, it is not possible to return a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span> instance in this method.  </p>  <p class="simpara">   Users are encouraged to include an <span class="property">_id</span> property (e.g. a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> initialized in the constructor)   when returning data for a BSON root document. In the absence of an   <span class="property">_id</span> property, the extension or server will generate a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> for insert or upsert   operations, respectively.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-persistable.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-persistable.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>, or <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>   to be serialized as a BSON document.  </p> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-persistable.bsonserialize-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">            <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>     <tr>      <td>PECL mongodb 1.17.0</td>      <td>       <span class="simpara">        This method may now also return <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>        instances in addition to <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> and <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-persistable.bsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\BSON\Serializable::bsonSerialize()} - Provides an array or document to serialize as BSON</span></li>   <li><span class="function">{@link MongoDB\BSON\Unserializable::bsonUnserialize()} - Constructs the object from a BSON array or document</span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-persistable.php" class="interfacename">MongoDB\BSON\Persistable</a></span></li>   <li><a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a></li>  </ul> </div></div>
 */
    public function bsonSerialize(): array|stdClass|Document;
}
